import type { PhotoCredit } from './credits';

/**
 * Every photograph the public site has used, with its credit (data only; the helpers are in
 * credits.ts, owned by the foundation lane). Generated by the imagery lane; sources, licences,
 * crops and slots are listed in docs/public-redesign/credits.md.
 *
 * Owner decisions, 20 Nov 2026: no image may show a recognisable university, and the site ships
 * with no photographs at all. Every entry below is the withdrawn campus set, kept for history only:
 * page-photos.ts never returns one, and PHOTO_CREDITS (the footer imprint) is empty while nothing
 * is in use. Their files (tinted, under /images/campus/<slug>/<crop>-<width>.{avif,webp}) are
 * left on disk for the lead to delete.
 *
 * When full-colour images are added later, give each a non-withdrawn entry here (with usedOn) and
 * point its slot at it in page-photos.ts; the footer then credits it automatically.
 */

export type CampusCropName = '4x5' | '3x4' | '4x3' | '16x9' | '1x1' | 'stamp-3x4';

export interface CampusFileSize {
  /** Real pixel width of the files at this step (also the key). */
  width: number;
  /** Real pixel height of the files at this step. */
  height: number;
  avifKb: number;
  webpKb: number;
}

export interface CampusCrop {
  aspect: { w: number; h: number };
  /** width in px -> public path */
  files: { avif: Record<number, string>; webp: Record<number, string> };
  /** width in px -> real pixel size and weight */
  sizes: Record<number, CampusFileSize>;
  /** Point of interest inside the crop, 0..1 (for object-position). */
  focal: { x: number; y: number };
  /** Page slots (lib/public/page-photos.ts) this crop fills; empty when withdrawn. */
  usedOn: readonly string[];
}

export interface CampusPhoto extends PhotoCredit {
  /** Same as id: the folder under /images/photos/ (neutral) or /images/campus/ (withdrawn). */
  slug: string;
  /** neutral: close-ups of a student's world; campus: named universities (withdrawn). */
  set: 'neutral' | 'campus';
  /** True for pictures that may no longer appear on any page. */
  withdrawn?: true;
  withdrawnReason?: string;
  /** Where a withdrawn picture used to be planned (history only). */
  formerlyUsedOn?: readonly string[];
  /** Title as published at the source. */
  sourceTitle: string;
  /** Plain description for captions. */
  place: string;
  creator: string;
  date?: string;
  licence: 'CC BY-SA 4.0' | 'CC BY 3.0' | 'CC0 1.0';
  licenceUrl: string;
  sourceUrl: string;
  via: 'Wikimedia Commons';
  /** Every file is tinted. */
  altered: true;
  /** CC BY-SA: the tinted version is shared under the same licence. */
  shareAlike: boolean;
  /** Long credit line, for figure captions and any credits page. */
  creditLine: string;
  /** Honest description of what the picture shows, for alt text. */
  altText: string;
  treated: true;
  /** The crop that files and focal below point at. */
  primaryCrop: CampusCropName;
  files: CampusCrop['files'];
  focal: CampusCrop['focal'];
  crops: Partial<Record<CampusCropName, CampusCrop>>;
}

