/** Alias with a clearer name for new code. */
export const SITE_PHOTOS = CAMPUS_PHOTOS;

/**
 * One credit per photograph a page actually shows: not withdrawn, and filling at least one slot.
 * Read by credits.ts (footer imprint and the Credit component).
 */
export const PHOTO_CREDITS: readonly PhotoCredit[] = CAMPUS_PHOTOS.filter(
  (photo) => !photo.withdrawn && Object.values(photo.crops).some((crop) => crop && crop.usedOn.length > 0)
);
